// === Tab: mySketch ===
let theShader = null;

function preload() {
	theShader = createShader(vert, frag);
}

function setup() {
	createCanvas(1112, 834, WEBGL);
	background(100);
	rectMode(CENTER);
	window.simulatedMouseX = width/2;
	window.simulatedMouseY = height/2;
}

function draw() {
	shader(theShader);
	background(0);
	theShader.setUniform('u_resolution', [width*2.13, height*2]);
	//theShader.setUniform('u_time', millis() / 1000);
	theShader.setUniform('u_time', ((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))+(window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))))/50);

	rect(0, 0, width, height);
}

function keyPressed(){
  save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg");
}

// === Tab: tab2 ===
const vert = `
	#ifdef GL_ES
		precision highp float;
		precision highp int;
	#endif

	// attribute, in
	attribute vec3 aNormal;
	attribute vec3 aPosition;
	attribute vec2 aTextCoord;
	attribute vec4 aTextColor;

	// attribute, out
	varying vec3 var_vartNormal;
	varying vec3 var_vartPosition;
	varying vec2 var_vartTextCoord;
	varying vec4 var_vartTextColor;

	// matrix 
	uniform mat3 uNormalMatrix;
	uniform mat4 uModelViewMatrix;
	uniform mat4 uProjectionMatrix;

	void main() {
		gl_Position = uProjectionMatrix * uModelViewMatrix * vec4(aPosition, 1.0);
	}
`;

// === Tab: tab3 ===
const frag = `
	#ifdef GL_ES
		precision mediump float;
	#endif

	uniform vec2 u_resolution;
	uniform float u_time;

	void main() {
 		vec2 position = -1.0 + 4.0 * gl_FragCoord.xy / u_resolution.xy * cos(1.0);

		float a001 = pow(abs(position.x) + abs(position.y), 0.5) / pow(abs(position.y) * abs(position.x), 0.5);
		float r001 = sqrt(dot(position, position));

		vec2 uv;
		uv.x = cos(a001) / r001;
		uv.y = sin(a001) / r001;
		uv /= 10.0;
		uv += u_time * 0.05;

		float color = 0.0;
		color += sin( uv.x * cos( u_time / 15.0 ) * 80.0 ) * cos( uv.y * cos( u_time / 15.0 ) * 80.0 );
		color += sin( uv.y * sin( u_time / 10.0 ) * 40.0 ) / cos( uv.x * sin( u_time / 25.0 ) * 40.0 );
		color += sin( uv.x * sin( u_time / 5.0 ) * 10.0 ) / sin( uv.y * sin( u_time / 35.0 ) * 80.0 );
		color *= sin( u_time / 10.0 ) * 0.5;

		gl_FragColor = vec4( vec3( color, color * 0.5, log( color + u_time / 3.0 ) * 0.75 ), 1.0 );
	}
`;

